<?php if(!defined('ABSPATH')){exit;}
$value=function($key){return isset($_GET[$key])&&is_scalar($_GET[$key])?sanitize_text_field(wp_unslash($_GET[$key])):'';}; ?>
<h2>فیلتر محصولات</h2><form method="get" action="<?php echo esc_url(is_product_taxonomy()?get_term_link(get_queried_object()):mht_url('shop.html')); ?>">
<?php if(is_search()): ?><input type="hidden" name="s" value="<?php echo esc_attr(get_search_query()); ?>"><input type="hidden" name="post_type" value="product"><?php endif; ?>
<div class="filter-section"><h3>دسته‌بندی‌ها</h3><a class="text-link" href="<?php echo esc_url(mht_url('shop.html')); ?>">همه محصولات</a>
<?php $terms=get_terms(['taxonomy'=>'product_cat','hide_empty'=>false,'orderby'=>'term_id']);if(!is_wp_error($terms)){foreach($terms as $parent){if($parent->parent){continue;}echo '<details><summary>'.esc_html($parent->name).'</summary><a href="'.esc_url(get_term_link($parent)).'">همه '.esc_html($parent->name).'</a>';foreach($terms as $child){if($child->parent===$parent->term_id){echo '<a href="'.esc_url(get_term_link($child)).'">'.esc_html($child->name).' <span class="muted">('.esc_html(mht_num($child->count)).')</span></a>';}}echo '</details>';}} ?></div>
<div class="filter-section"><h3>برند</h3><select name="brand" aria-label="برند"><option value="">همه برندها</option><?php $brands=taxonomy_exists('product_brand')?get_terms(['taxonomy'=>'product_brand','hide_empty'=>true,'fields'=>'names']):[];if(is_wp_error($brands)){$brands=[];}if(!$brands){$brands=['Apple','Samsung','Xiaomi','Sony','Anker','JBL','Honor'];}foreach($brands as $brand): ?><option value="<?php echo esc_attr($brand); ?>" <?php selected($value('brand'),$brand); ?>><?php echo esc_html($brand); ?></option><?php endforeach; ?></select></div>
<div class="filter-section"><h3>محدوده قیمت (<?php echo esc_html(get_woocommerce_currency_symbol()); ?>)</h3><div class="price-inputs"><label>از<input name="min_price" type="number" min="0" value="<?php echo esc_attr($value('min_price')); ?>"></label><label>تا<input name="max_price" type="number" min="0" value="<?php echo esc_attr($value('max_price')); ?>"></label></div></div>
<div class="filter-section"><label class="check-label"><input type="checkbox" name="instock" value="1" <?php checked($value('instock'),'1'); ?>> فقط کالاهای موجود</label><label class="check-label"><input type="checkbox" name="sale" value="1" <?php checked($value('sale'),'1'); ?>> فقط تخفیف‌دارها</label></div>
<button class="button dark">اعمال فیلترها</button><a class="button outline" href="<?php echo esc_url(mht_url('shop.html')); ?>">پاک کردن فیلترها</a></form>
